  "claims": [
    {
      "claim": "L3 cocaine exposure records confirm substantial oral systemic exposure in humans: 100 mg oral cocaine gave AUC 235 ng·h/mL and Cmax 115 ng/mL, 200 mg gave AUC 654 ng·h/mL and Cmax 268 ng/mL, with oral/IV AUC ratios of 0.8 and 2.1 versus 40 mg IV, consistent with L1 F values of about 32% and 45%.",
      "card_ids": ["C134", "C139", "C142", "C152", "C171", "C174"]
    },
    {
      "claim": "Oral cocaine 2 mg/kg AUC was 22.3 µg/ml·min, similar to intranasal AUC 23.3 µg/ml·min, corroborating similar oral and intranasal bioavailability for this tertiary tropane ester.",
      "card_ids": ["C145", "C155"]
    },
    {
      "claim": "Felbamate L3 exposure records show high oral exposure with AUC 416 µg·hr/ml after 600 mg BID and Cmax 64.4 mg/L after 200 mg, consistent with its high L1 bioavailability, but the scaffold is less transferable to scopolamine.",
      "card_ids": ["C156", "C180"]
    },
    {
      "claim": "Benzoylecgonine AUC ratio records reflect a cocaine metabolite and do not inform scopolamine oral bioavailability.",
      "card_ids": ["C160", "C163", "C164", "C165"]
    },
    {
      "claim": "Quaternary ammonium analogs ipratropium and tiotropium have L1 F of 2-3%, but scopolamine is a tertiary amine, so these low-F records are less transferable.",
      "card_ids": ["C04", "C07", "C08", "C29", "C54"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C134", "C139", "C142", "C145", "C152", "C155", "C171", "C174"]
    },
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C151", "C156", "C158", "C180"]
    },
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "not_applicable",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C160", "C163", "C164", "C165"]
    }
  ],
  "evidence_gaps": [
    "No direct scopolamine oral bioavailability or exposure record is supplied.",
    "L3 records cover cocaine, benzoylecgonine, and felbamate, not scopolamine.",
    "Atropine F 21.62% is from rats and may not fully transfer to humans.",
    "Scopolamine is mostly ionized at physiological pH with neutral fraction 0.27, which may reduce permeability, but this is not affirmative evidence for F below 20%.",
    "Cocaine lacks the tropate ester and 6,7-epoxide of scopolamine, so ester hydrolysis and first-pass differences remain uncertain."
  ],
  "decision_summary": "L3 oral exposure records for cocaine, the closest tertiary-amine tropane ester analog, confirm meaningful oral systemic exposure in humans with oral/IV AUC ratios consistent with F about 32-45%, strengthening the high prediction for scopolamine; felbamate records are less transferable and benzoylecgonine records are not applicable, and no L3 record contradicts the high prediction."
}

